<template>
    <div class="video">
        <div class="wrap">
            <Button @click="refresh" type="text" size="small" icon="md-refresh">刷新</Button>
            <Button @click="doSDomain" type="text" size="small" icon="md-settings">设置</Button>
            <div style="width: 35%;"><Input v-model="formS.v_domain" size="small" name="v_domain"
             placeholder="请输入当前要监控的视频所属域名地址,多个使用逗号分隔,非监控域名直接过滤..."></Input></div>
            <Poptip max-width="200" placement="left" content="如果返回的地址比较混乱,可以设置重点监控几个域名的视频地址;减少数据误差...">
                <Icon type="ios-help-circle-outline" size="20" />
            </Poptip>
        </div>
        <Table stripe border :columns="columns" :data="mStore.video">
            <template #action="{ row }">
                <Button type="success" size="small" @click="download(row)">下载</Button>&nbsp;
                <Button type="error" size="small" @click="remove(row)">删除</Button>
            </template>
            <template #title="{ row }">
                <a target="_blank" :href="row.page">{{ row.title }}</a>
            </template>
            <template #src="{ row }">
                <a target="_blank" :href="row.src">{{ row.src }}</a>
            </template>
        </Table>
        <div style="margin-top: 8px;">
            <Page :total="mStore.vodTotal" show-sizer :page-size="mStore.mPagesize"
                @on-change="pageSelected" @on-page-size-change="setPagesize" />
        </div>
    </div>
</template>
<script setup>
import { onMounted, ref } from 'vue';
import { Table, Button, Input, Page, Icon, Poptip, Message } from 'view-ui-plus';
import { useMediaStore } from '@/app/store/media';
import utilSrv from "@/static/js/base/utils";
import messageSrv from "@/static/js/base/m-sender";

const link = ref('');
const emit = defineEmits(['edit']);
const mStore = useMediaStore();
const formS = ref({v_domain:''});
const columns = [
    {
        title: '记录ID',
        key: 'id',
        maxWidth: 100,
        minWidth: 60,
        resizable: true,
    },
    {
        title: '页面标题',
        maxWidth: 360,
        minWidth: 160,
        key: 'title',
        resizable: true,
        slot: 'title',
    },
    {
        title: '视频地址',
        key: 'src',
        minWidth: 160,
        resizable: true,
        slot: 'src',
    },
    {
        title: '更新时间',
        maxWidth: 140,
        minWidth: 100,
        resizable: true,
        key: 'created_at'
    },
    {
        title: '操作',
        slot: 'action',
        maxWidth: 140,
        minWidth: 100,
        resizable: true,
        align: 'center'
    }
];

const remove = async (row) => {
    await mStore.deleteMedia(row.id, 0);
};

const pageSelected = async (curPage) => {
    await mStore.loadVideo(curPage, link.value);
};

const setPagesize = async(pSize) => {
    mStore.mPagesize = pSize;
    await mStore.loadVideo(1, link.value);
}

const refresh = async() => {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (tab && tab.url) {//地址
       link.value = tab.url
    }
    await mStore.loadVideo(1, link.value);
}

//设置监控域名
const doSDomain = async() => {
    const sKey = await utilSrv.Vdomain('');
    if (sKey && sKey.length > 0) {
        if (!formS.value.v_domain) {
            await chrome.storage.local.remove(sKey);
            Message.success('清理关注视频域名成功');
        } else {//保存
            await chrome.storage.local.set({ [sKey]: formS.value.v_domain });
            Message.success('关注视频域名设置成功');
        }
    } else {
        Message.error('当前环境无法操作') 
    }
}

//下载操作
const download = async (row) => {
    const params = {type: utilSrv.msgTypeDownloadMedia};
    params.video = [row.src]; //地址资料信息
    params.title = row.title; //标题资料信息
    const response = await messageSrv.doSendMessage(params);
    if (response && response.code === 0) {
        Message.success('操作完成');
    } else {
        utilSrv.Write(utilSrv.INFO, "操作失败", response);
        Message.error('操作失败,刷新重新操作');
    }
}

const initConfig = async() => {
    const sKey = await utilSrv.Vdomain('');
    if (sKey && sKey.length > 0) {
        const vDomain = await chrome.storage.local.get(sKey);
        formS.value.v_domain = vDomain[sKey] || '';
    }
}

onMounted(async ()=>{
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (tab && tab.url) {//地址
       link.value = tab.url
    }
    await mStore.loadVideo(1, link.value);
    initConfig();//初始化配置的逻辑
    chrome.tabs.onActivated.addListener(async (activeInfo) => {
        initConfig();
    });
})
</script>

<style scoped>
.wrap {
    padding: 8px;
    background-color: #aaa;
    display: flex;
    align-items: center;
    gap: 8px;
}
</style>