<template>
    <div class="items">
        <div class="wrap">
            <span class="search">
              <Input type="text" size="small" v-model="search.query" placeholder="请输入导出关键词过滤..."/>
            </span>
            <span class="actions" @click.stop>
              <Button @click="rnExport" type="text" size="small" icon="md-cloud-download">导出</Button>
              <Button @click="refresh" type="text" size="small" icon="md-refresh">刷新</Button>
            </span>
        </div>
        <Table stripe border :columns="columns" :data="dataStore.items">
            <template #action="{ row }">
                <Button type="primary" size="small" @click="copy(row)">复制</Button>&nbsp;
                <Button type="success" size="small" @click="download(row)">下载</Button>&nbsp;
                <Button type="error" size="small" @click="remove(row)">删除</Button>
            </template>
            <template #title="{ row }">
                <a target="_blank" :href="row.link">{{ row.meta.title || row.meta.desc || '--'}}</a>
            </template>
            <template #desc="{ row }">
                <div class="ellipsis-multi">
                    {{ row.meta.desc || row.meta.detail }} 
                </div>
                <span v-for="(src, index) in row.meta.images" class="p-r-15">
                    <a target="_blank" :href="src">图片[{{ index+1 }}]</a>
                </span>
                <span v-if="row.meta.video" class="p-r-15">
                    <a target="_blank" :href="row.meta.video">主视频</a>
                </span>
                <span v-for="(src, index) in row.meta.videos" class="p-r-15">
                    <a target="_blank" :href="src">视频[{{ index+1 }}]</a>
                </span>
            </template>
        </Table>
        <div style="margin-top: 8px;">
            <Page :total="dataStore.total" show-sizer :page-size="dataStore.mPagesize"
                @on-change="pageSelected" @on-page-size-change="setPagesize" />
        </div>
    </div>
</template>
<script setup>
import { onMounted, ref, reactive } from 'vue';
import { Table, Button, Page, Message, Input } from 'view-ui-plus';
import { useStore } from '@/app/store/index';
import utilSrv from "@/static/js/base/utils";
import messageSrv from "@/static/js/base/m-sender";
import { useProductsStore } from '@/app/store/products';
import { ProductsSrv } from '@/static/js/index-db/products.srv';
import { showLoading, hideLoading } from '@/app/static/loading';

const link = ref('');
const currPage = ref(1);
const mStore = useStore();
const dataSrv = new ProductsSrv();
const emit = defineEmits(['edit']);
const search = reactive({query:''});
const dataStore = useProductsStore();

const columns = [
    {
        title: '记录ID',
        key: 'sn',
        width: 160,
        maxWidth: 160,
        minWidth: 80,
        resizable: true,
    },
    {
        title: '标题',
        minWidth: 140,
        key: 'title',
        resizable: true,
        slot: 'title',
    },
    {
        title: '内容',
        key: 'desc',
        minWidth: 200,
        resizable: true,
        slot: 'desc',
    },
    {
        title: '更新时间',
        maxWidth: 140,
        minWidth: 100,
        resizable: true,
        key: 'created_at'
    },
    {
        title: '操作',
        slot: 'action',
        maxWidth: 200,
        minWidth: 100,
        resizable: true,
        align: 'center'
    }
];

//电商产品的导出字段
const defHeader = [{key: 'sn', title: '编号[asin]'}, {key: 'meta.title', title: '标题[title]'}, {key: 'meta.sold_by', title: '卖家名称[sold_by]'},
    {key: 'meta.seller_id', title: '卖家ID[seller_id]'}, {key: 'meta.ships_from', title: '发货地[ships_from]'},{key: 'meta.price', title: '价格[price]'},
    {key: 'meta.secondary_price', title: '列表价格[secondary_price]'},{key: 'meta.description', title: '商品描述[description]'},{key: 'meta.features', title: '五点描述[features]'},
    {key: 'meta.detail', title: '商品详情[detail]'}, {key: 'meta.brand', title: '品牌[brand]'},{key: 'meta.brand_store', title: '品牌店铺[brand_store]'},
    {key: 'meta.category', title: '归属类目[category]'},{key: 'meta.delivery_price', title: '运费[delivery_price]'},{key: 'meta.images', title: '商品图片[images]'},
    {key: 'meta.video', title: '视频[video]'}, {key: 'meta.ratings', title: '评论数[ratings]'}, {key: 'meta.score', title: '评分[score]'}, {key: 'meta.best_sellers', title: 'Best Seller标识[best_sellers]'}, 
    {key: 'meta.best_seller_rank', title: '类目热销排名[best_seller_rank]'},{key: 'meta.available_date', title: '上架日期[available_date]'}, {key: 'meta.manufacturer', title: '产商[manufacturer]'}, 
    {key: 'meta.item_weight', title: '商品重量[item_weight]'},{key: 'meta.product_dimensions', title: '体积[product_dimensions]'}];

//根据路径获取对象的值
function getByPath(obj, path) {
  return path.split('.').reduce((acc, k) => acc?.[k], obj);
}

const remove = async (row) => {
    await dataStore.delete(row.sn);
};

const pageSelected = async (curPage) => {
    currPage.value = curPage;
    await dataStore.load(curPage, link.value);
};

const setPagesize = async(pSize) => {
    dataStore.mPagesize = pSize;
    await dataStore.load(1, link.value);
};

const refresh = async() => {//刷新
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (tab && tab.url) {//地址
       link.value = tab.url
    }
    await dataStore.load(1, link.value);
};

//导出关键词过滤
const myFilter = (item, words) => {
    const title = item.meta.title || item.meta.desc || '';
    for (let i = 0; i < words.length; i++) {
        const str = words[i];
        if (title.includes(str)) {
            return true
        }
    }
    return false;
};

//标题业务处理逻辑
const myTitle = () => {
  const domain = mStore.curDomain;
  const items = mStore.dict.items || [];
  const dtItem = items.find((item)=>{
    return domain.includes(item.value);
  });
  return dtItem? dtItem.label:'实体';
};

//组装单条记录的评论文本，回复按缩进展示
const buildText = (row) => {
    const item = JSON.parse(JSON.stringify(row));
    item.meta.images = item.meta.images? item.meta.images.join("\n"):'';
    item.meta.videos = (item.meta.videos && item.meta.videos.length > 0)? item.meta.videos[0]:'';
    const raw = defHeader.map((f)=>{
        return f.title + ': ' + getByPath(item, f.key);
    });
    return raw.join('\n');
};

//复制操作
const copy = async (row) => {
    showLoading("评论复制中...");
    const text = buildText(row);
    const ok = await utilSrv.writeClipboard(text);
    hideLoading();
    if (ok) {
        Message.success(`复制成功`);
    } else {
        Message.error('复制失败，请检查浏览器剪贴板权限');
    }
};


//导出的业务逻辑
const rnExport = async() => {
  if (dataStore.total < 1) {
    Message.error('暂时没有数据');
    return;
  }
  const domain = mStore.curDomain;
  search.query = search.query.replaceAll('，', ',');
  const words = (search.query)? search.query.split(','):null;
  const lines = [defHeader.map(f => f.title).join(',')];
  await dataSrv.Curor(10000, domain, (item)=>{
    if (words && !myFilter(item, words)) {
      return;//没有包含指定关键词跳过
    }
    item.meta.images = item.meta.images? item.meta.images.join("\n"):'';
    item.meta.videos = (item.meta.videos && item.meta.videos.length > 0)? item.meta.videos[0]:'';
    const raw = defHeader.map(f => getByPath(item, f.key));
    const line = raw.map(v => {
      const s = String(v ?? '').replace(/"/g, '');
      return `"${s}"`;
    });
    lines.push(line.join(','));
  });
  const csv  = '\uFEFF' + lines.join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = myTitle()+`数据_${Date.now()}.csv`;
  a.click();
  URL.revokeObjectURL(url);
};

//下载操作
const download = async (row) => {
    let response = null; //回传内容
    const title  = row.meta.title || row.sn; //标题资料信息
    const params= {title: title};
    try {
        showLoading("资料下载中...");
        params.type = utilSrv.msgTypeDownloadMedia;
        params.image = row.meta.images;
        //视频保存一个即可,多个都传，能下载的一个就结束
        params.video = row.meta.videos? row.meta.videos:[];
        if (row.meta.video) {
            params.video.push(row.meta.video);
        }
        response = await messageSrv.doSendMessage(params);
        setTimeout(()=>{
            hideLoading(); //隐藏
        }, 1500);
        if (!response || response.code !== 0) {
            utilSrv.Write(utilSrv.INFO, "操作失败", response);
            Message.error('操作失败,刷新重新操作');
        }
    } catch (errS) {
        utilSrv.Write(utilSrv.INFO, "下载失败", errS);
    } finally {//总是会自动执行
        setTimeout(()=>{//休眠3秒钟执行下载的逻辑
            hideLoading();
        }, 7000);
    }
}

onMounted(async ()=>{
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (tab && tab.url) {//地址
       link.value = tab.url
    }
    await dataStore.load(1, link.value);
})
</script>
<style scoped>
.p-r-15 {
    padding-right: 15px;
}
.ellipsis-multi {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;   /* 显示 2 行，超出省略 */
  overflow: hidden;
}
.wrap {
    padding: 8px 0;
    background-color: #aaa;
    display: flex;
    justify-content: space-between;
    align-items: center; 
    .search {
        padding-left: 8px;
    }
    .actions{
        padding-right: 8px;
    }
}
</style>