import { defineStore } from 'pinia'
import utilSrv from "@/static/js/base/utils";
import { CacheSrv } from '@/static/js/index-db/cache.srv';
import { CacheRefType } from "@/static/js/index-db/idb-schema";
import { myTools, getToolScript } from '../static/api';

const cacheSrv = new CacheSrv();
export const useToolsStore = defineStore('Tools', {
    state: () => {
      return {
        tools: [],
        script: {},
        tolTotal: 0,
      }
    },

    actions: {
      async loadTools(params) {
        const data = await myTools(params);
        if (data) {//加载工具
          this.tolTotal = data.total;
          this.tools = [...data.items];
        }
      },
      async myScript(uuid) {
        if (this.script && this.script[uuid]) {
          return this.script[uuid]; //返回脚本
        }
        const data = await getToolScript(uuid);
        this.script[uuid] = data.script || ''; //缓存脚本
        return data.script || '';
      },
      async runXTool(tab, tool) {
        if (tool && tool.runtime === 'page') {//直接UI上执行
          const es5Code = await this.myScript(tool.sn);
          if (es5Code) {//发送执行脚本的情况
            const params= { type: utilSrv.msgTypeRunScript, 
              script: es5Code, run_ctx: 'content_script' };
            await chrome.tabs.sendMessage(tab.id, params);
          }
        } else {//默认-主要注入上下文执行
          const meta = {from:'x.tools', id:(tool && tool.script_id)? tool.script_id:0, is_window:0, link:tab.url, priority:0, status:2,
            opcmd:0, script:'', run_ctx:'content_script', script_uuid:'', timeout:3};
          if (tool && tool.sn) {//数据业务逻辑
            meta.script_uuid = tool.sn;
          }
          const sKey = await utilSrv.Sdomain(tab.url);
          await cacheSrv.SetCache(sKey, CacheRefType.domain, meta);
          await chrome.tabs.reload(tab.id);//重置并刷新执行
        }
      },
    }
});


