`, "",{"version":3,"sources":["webpack://./src/app/popup/index/components/script.vue"],"names":[],"mappings":";AA8IA;IACI,YAAY;IACZ,sBAAsB;IACtB,aAAa;IACb,mBAAmB;IACnB,QAAQ;AACZ","sourcesContent":["<template>\r\n    <div class=\"script\">\r\n        <div class=\"wrap\">\r\n            <Button @click=\"refresh\" type=\"text\" size=\"small\" icon=\"md-refresh\">刷新</Button>\r\n        </div>\r\n        <Table stripe border :columns=\"columns\" :data=\"myScript\">\r\n            <template #action=\"{ row }\">\r\n                <Button type=\"success\" size=\"small\" style=\"margin-right: 5px\" @click=\"exec(row)\">执行</Button>\r\n                <Button v-if=\"row.meta && row.meta.script\" type=\"primary\" size=\"small\" style=\"margin-right: 5px\" @click=\"edit(row)\">编辑</Button>\r\n                <span v-else>&nbsp;&nbsp;</span>\r\n                <Button v-if=\"row.meta && row.meta.script\" type=\"error\" size=\"small\" @click=\"remove(row)\">删除</Button>\r\n            </template>\r\n        </Table>\r\n    </div>\r\n</template>\r\n<script setup>\r\nimport { onMounted, computed } from 'vue';\r\nimport { Table, Button } from 'view-ui-plus';\r\nimport { useStore } from '@/app/store/index';\r\nimport utilSrv from \"@/static/js/base/utils\";\r\nimport { xIsLogin } from \"@/static/js/base/request\";\r\nimport { useDevelopStore } from '@/app/store/develop';\r\nimport {CacheSrv} from \"@/static/js/index-db/cache.srv\";\r\nimport {CacheRefType} from \"@/static/js/index-db/idb-schema\";\r\nimport { deleteScript, GetScripts } from \"@/app/static/api.js\";\r\n\r\nconst emit   = defineEmits(['edit']);\r\nconst mStore = useStore();\r\nconst dStore = useDevelopStore();\r\n//当前域名下的脚本\r\nconst myScript = computed(()=>{\r\n    return dStore.script.filter((item)=>{\r\n        if (!item.meta || !mStore.curDomain) {\r\n            return false;\r\n        }\r\n        const host = item.meta.host || item.meta.match;\r\n        if (host.includes('//*.*') || host.includes('//*')) {\r\n            return true;\r\n        }\r\n        return host.includes(mStore.curDomain);\r\n    });\r\n});\r\n\r\nconst columns = [\r\n    {\r\n        title: '脚本名称',\r\n        key: 'name',\r\n        maxWidth: 240,\r\n        minWidth: 100,\r\n        resizable: true,\r\n    },\r\n    {\r\n        title: '版本',\r\n        maxWidth: 100,\r\n        minWidth: 60,\r\n        resizable: true,\r\n        key: 'version'\r\n    },\r\n    {\r\n        title: '作者',\r\n        maxWidth: 140,\r\n        minWidth: 100,\r\n        resizable: true,\r\n        key: 'author'\r\n    },\r\n    {\r\n        title: '脚本描述',\r\n        key: 'description',\r\n        minWidth: 200,\r\n        resizable: true,\r\n    },\r\n    {\r\n        title: '更新时间',\r\n        maxWidth: 140,\r\n        minWidth: 100,\r\n        key: 'created_at',\r\n        resizable: true,\r\n    },\r\n    {\r\n        title: '操作',\r\n        slot: 'action',\r\n        maxWidth: 180,\r\n        minWidth: 100,\r\n        resizable: true,\r\n        align: 'center'\r\n    }\r\n];\r\n\r\nconst edit = (row) => {\r\n    emit('edit', row);\r\n};\r\n\r\nconst remove = async (row) => {\r\n    if (row.meta && row.meta.id) {\r\n        const result = await deleteScript({id:row.meta.id});\r\n        if (!result) {\r\n            return;\r\n        }\r\n    }\r\n    await dStore.deleteScript(row.skey);\r\n};\r\n\r\nconst exec = async (row) => {\r\n    try {\r\n        const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });\r\n        if (tab && tab.url && tab.url.startsWith('http')) {\r\n            const isOK = await mStore.openSetting(tab);\r\n            if (isOK) {\r\n                await dStore.runScript(row.meta.script, row.meta);\r\n            }\r\n        }\r\n    } catch(errS) {\r\n        utilSrv.Write(utilSrv.INFO, \"异步执行异常\", errS);\r\n        Message.error(errS.message);//失败的情况\r\n    }\r\n}\r\n\r\nconst initScript = async() => {\r\n  const cacheSrv = new CacheSrv();\r\n  const sData = await GetScripts();\r\n  if (sData && sData.items) {\r\n    sData.items.forEach(async(meta)=>{\r\n      const sKey = 'script@'+meta.name;\r\n      await cacheSrv.SkipCache(sKey, CacheRefType.script, meta);\r\n    });\r\n  }\r\n};\r\n\r\nconst refresh = async() => {\r\n  const isLogin = await xIsLogin();\r\n  if (isLogin) {\r\n    initScript(); //开发者模式才加载\r\n  }\r\n  await dStore.loadScript();\r\n};\r\n\r\nonMounted(async ()=>{\r\n    await dStore.loadScript();\r\n});\r\n</script>\r\n\r\n<style scoped>\r\n.wrap {\r\n    padding: 8px;\r\n    background-color: #aaa;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 8px;\r\n}\r\n</style>"],"sourceRoot":""}]);
