import { defineStore } from 'pinia'
import utilSrv from "@/static/js/base/utils";
import { getXConfig } from '../static/api';

const level = process.env.APP_VERCODE;
export const useStore = defineStore('Index', {
    state: () => {
      return {
        script: [],
        template: [],
        mPagesize: 10,
        user: null,
        token: '',
        dict: {},
        version: {},
        developerMode: false,
        curDomain: '',
        setting: {
          site_sniffer:false,
          site_message:false,
          site_wasm:false,
        }
      }
    },
    getters: {
      isManager: (state) =>{
        return state.user && state.user.isManager;
      },
      isDeveloper: (state) =>{
        return Boolean(state.user && state.developerMode);
      }
    },
    actions: {
      async signIn(xToken, user) {
        this.user = user;
        this.token= xToken;
        if (!user) {
          this.developerMode = false;
        }
      },
      async loadDict() {
        const data = await getXConfig(level);
        if (data && data.dict) {//加载字典
          this.dict = {...data.dict};
        }
        if (data && data.version) {//加载版本
          this.version = data.version;
        } else {//代表已经加载了
          this.version.ver = 1;
        }
      },
      async loadDeveloperMode() {
        const data = await chrome.storage.local.get('developerMode');
        this.developerMode = Boolean(this.user && data.developerMode);
      },
      async setDeveloperMode(enabled) {
        this.developerMode = Boolean(this.user && enabled);
        await chrome.storage.local.set({developerMode:this.developerMode});
      },
      async initSetting(tab) {
        if (!tab || !tab.url || !tab.id) {
          return;
        }
        const sKey = await utilSrv.Sdomain(tab.url);
        this.curDomain = sKey; //当前的页面地址
        const data = await chrome.storage.local.get(sKey);
        this.setting.site_sniffer = false;
        if (data[sKey] && data[sKey].n === 1) {
          this.setting.site_sniffer = true;
        } 
        this.setting.site_message = false;
        if (data[sKey] && data[sKey].m === 1) {
          this.setting.site_message = true;
        } 
        this.setting.site_wasm = false;
        if (data[sKey] && data[sKey].w === 1) {
          this.setting.site_wasm = true;
        }
      },
      async svSetting(tab, isReset=false) {
        if (!tab || !tab.url || !tab.id) {
          return;
        }
        const sKey = await utilSrv.Sdomain(tab.url);
        const state = { n: 0, m: 0, w:0 };
        if (isReset) {//重置的逻辑
          this.setting.site_wasm = false;
          this.setting.site_sniffer = false;
          this.setting.site_message = false;
        } 
        state.n = this.setting.site_sniffer? 1:0;
        state.m = this.setting.site_message? 1:0;
        state.w = this.setting.site_wasm? 1:0;
        await chrome.storage.local.set({ 
          [sKey]: state
        });
        await chrome.tabs.reload(tab.id);
      },
      async openSetting(tab) {
        const sKey = await utilSrv.Sdomain(tab.url);
        if (!sKey) {//域名地址提取失败
          return true;
        }
        let isOpStep = 0;
        if (!this.setting.site_sniffer) {
          isOpStep++;
          this.setting.site_sniffer = true;
        }
        if (!this.setting.site_message) {
          isOpStep++;
          this.setting.site_message = true;
        }
        if (!this.setting.site_wasm) {
          isOpStep++;
          this.setting.site_wasm = true;
        }
        if (isOpStep > 0) {//重置并刷新执行
          await this.svSetting(tab, false);
          return false;
        }
        return true;
      }
    },
});