<template>
  <div class="data-center">
    <section class="data-card collection-card">
      <div class="section-heading">
        <div>
          <h2>采集数据管理</h2>
          <p>{{ dataDescription }}</p>
        </div>
        <span class="domain-pill">
          <i :class="{ online: !!iTitle || !!pTitle || !!cTitle }"></i>
          {{ iTitle || pTitle || cTitle || '当前站点' }}
        </span>
      </div>

      <Collapse v-if="isData" v-model="cPanel" accordion class="data-collapse">
        <Panel v-if="iTitle" name="items">
          <template #default>
            <span class="panel-label">
              <span class="panel-icon collector"><Icon type="ios-list-box" /></span>
              <span>
                <strong>{{ iTitle }}</strong>
                <small>{{ itemsStore.total }} 条采集记录</small>
              </span>
            </span>
          </template>
          <template #content>
            <div class="table-shell"><CItems /></div>
          </template>
        </Panel>
        <Panel v-if="pTitle" name="products">
          <template #default>
            <span class="panel-label">
              <span class="panel-icon collector"><Icon type="ios-list-box" /></span>
              <span>
                <strong>{{ pTitle }}</strong>
                <small>{{ productsStore.total }} 条采集记录</small>
              </span>
            </span>
          </template>
          <template #content>
            <div class="table-shell"><CProducts /></div>
          </template>
        </Panel>
        <Panel v-if="cTitle" name="comments">
          <template #default>
            <span class="panel-label">
              <span class="panel-icon template"><Icon type="ios-list-box" /></span>
              <span>
                <strong>{{ cTitle }}</strong>
                <small>{{ commsStore.total }} 条采集记录</small>
              </span>
            </span>
          </template>
          <template #content>
            <div class="table-shell"><CComments /></div>
          </template>
        </Panel>
        <Panel v-if="mStore.isManager" name="image">
          <template #default>
            <span class="panel-label">
              <span class="panel-icon image"><Icon type="md-images" /></span>
              <span>
                <strong>图片资源</strong>
                <small>{{ mediaStore.imgTotal }} 条当前页面缓存</small>
              </span>
            </span>
          </template>
          <template #content>
            <div class="table-shell"><CImage /></div>
          </template>
        </Panel>
        <Panel v-if="mStore.isManager" name="video">
          <template #default>
            <span class="panel-label">
              <span class="panel-icon video"><Icon type="ios-videocam" /></span>
              <span>
                <strong>视频资源</strong>
                <small>{{ mediaStore.vodTotal }} 条当前页面缓存</small>
              </span>
            </span>
          </template>
          <template #content>
            <div class="table-shell"><CVideo /></div>
          </template>
        </Panel>
      </Collapse>
      <div v-else class="empty-state">
        <span><Icon type="ios-folder-open-outline" size="28" /></span>
        <strong>当前页面暂无可管理数据</strong>
        <p>打开小红书、抖音或B站页面并运行采集工具后，数据会显示在这里。</p>
      </div>
    </section>
  </div>
</template>
<script setup>
import { ref, computed } from 'vue';
import { Collapse, Panel, Icon } from 'view-ui-plus';
import { useStore } from '@/app/store/index';

import CVideo from './video.vue';
import CImage from './image.vue';
import CItems from './items.vue';
import CProducts from './products.vue';
import CComments from './comments.vue';

import { useMediaStore } from '@/app/store/media';
import { useItemsStore } from '@/app/store/items';
import { useProductsStore } from '@/app/store/products';
import { useCommentsStore } from '@/app/store/comments';

const cPanel  = ref('');
const mStore = useStore();
const itemsStore = useItemsStore();
const mediaStore = useMediaStore();
const commsStore = useCommentsStore();
const productsStore = useProductsStore();

//是否包含数据
const isData = computed(()=>{
  if (mStore.isManager) {
    return true;
  }
  return !!iTitle.value || !!pTitle.value || !!cTitle.value;
});

const iTitle = computed(()=>{
  const domain = mStore.curDomain;
  const items = mStore.dict.items || [];
  const dtItem = items.find((item)=>{
    return domain.includes(item.value);
  });
  return dtItem? dtItem.label:'';
});

const pTitle = computed(()=>{
  const domain = mStore.curDomain;
  const items = mStore.dict.products || [];
  const dtItem = items.find((item)=>{
    return domain.includes(item.value);
  });
  return dtItem? dtItem.label:'';
});

const cTitle = computed(()=>{
  const domain = mStore.curDomain;
  const items = mStore.dict.comments || [];
  const dtItem = items.find((item)=>{
    return domain.includes(item.value);
  });
  return dtItem? dtItem.label:'';
});

const dataDescription = computed(() => {
  if (iTitle.value) {
    return `当前已识别为${iTitle.value}页面，可在下方查看、导出与维护采集结果。`;
  }
  if (pTitle.value) {
    return `当前已识别为${pTitle.value}页面，可在下方查看、导出与维护采集结果。`;
  }
  return '按当前站点集中查看采集结果、图片和视频资源。';
});
</script>
<style scoped>
.data-center {
  display: grid;
  gap: 12px;
}
.data-card {
  padding: 15px;
  background: #ffffff;
  border: 1px solid #e6ebf2;
  border-radius: 16px;
  box-shadow: 0 6px 20px rgba(15, 23, 42, 0.045);
}
.section-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 13px;
}
.section-kicker {
  display: block;
  margin-bottom: 2px;
  color: #2563eb;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}
.section-heading h2 {
  margin: 0;
  color: #172033;
  font-size: 16px;
  line-height: 23px;
}
.section-heading p {
  margin: 3px 0 0;
  color: #7c879d;
  font-size: 12px;
  line-height: 18px;
}
.domain-pill {
  display: inline-flex;
  align-items: center;
  flex: none;
  gap: 5px;
  max-width: 155px;
  padding: 4px 8px;
  overflow: hidden;
  color: #667085;
  background: #f4f6f9;
  border-radius: 999px;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.domain-pill i {
  width: 6px;
  height: 6px;
  flex: none;
  background: #cbd5e1;
  border-radius: 50%;
}
.domain-pill i.online {
  background: #22c55e;
  box-shadow: 0 0 0 3px #dcfce7;
}

.data-collapse {
  overflow: hidden;
  border: 1px solid #edf0f5;
  border-radius: 12px;
}
.data-collapse :deep(.ivu-collapse-header) {
  display: flex;
  align-items: center;
  min-height: 62px;
  padding-right: 10px;
  color: #344054;
  background: #fbfcfe;
}
.data-collapse :deep(.ivu-collapse-content) {
  padding: 0;
}
.data-collapse :deep(.ivu-collapse-content-box) {
  padding: 12px;
}
.panel-label {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  gap: 9px;
  vertical-align: middle;
}
.panel-label strong,
.panel-label small {
  display: block;
  line-height: 18px;
}
.panel-label strong {
  color: #344054;
  font-size: 13px;
}
.panel-label small {
  color: #98a2b3;
  font-size: 11px;
}
.panel-icon {
  display: inline-grid;
  width: 34px;
  height: 34px;
  border-radius: 9px;
  place-items: center;
  font-size: 17px;
}
.panel-icon.collector {
  color: #2563eb;
  background: #eff6ff;
}
.panel-icon.image {
  color: #0891b2;
  background: #ecfeff;
}
.panel-icon.video {
  color: #7c3aed;
  background: #f5f3ff;
}
.panel-icon.script {
  color: #b45309;
  background: #fffbeb;
}
.panel-icon.template {
  color: #475569;
  background: #f1f5f9;
}

.table-shell {
  overflow-x: auto;
  border-radius: 8px;
}
.empty-state {
  padding: 25px 18px;
  color: #98a2b3;
  text-align: center;
  background: #fbfcfe;
  border: 1px dashed #d8dee8;
  border-radius: 12px;
}
.empty-state > span {
  display: grid;
  width: 48px;
  height: 48px;
  margin: 0 auto 8px;
  color: #2563eb;
  background: #eff6ff;
  border-radius: 14px;
  place-items: center;
}
.empty-state strong {
  display: block;
  color: #475467;
  font-size: 13px;
}
.empty-state p {
  max-width: 420px;
  margin: 5px auto 0;
  font-size: 11px;
  line-height: 18px;
}

@media (max-width: 520px) {
  .section-heading {
    align-items: stretch;
    flex-direction: column;
  }
  .domain-pill {
    align-self: flex-start;
  }
}
</style>
