\";\nimport utilSrv from \"@/static/js/base/utils\";\nimport { onMounted, onBeforeUnmount, reactive } from 'vue';\nimport { useStore } from '@/app/store/index';\nimport CTools from './components/tools.vue';\nimport CEditor from './components/editor.vue';\nimport CDataset from './components/dataset.vue';\nimport CFeedback from './components/feedback.vue';\nimport CProfile from './components/profile.vue';\n\nconst mStore = useStore();\nconst dataState = reactive({n_task:0});\n\n//切换tab的情况加载模版\nconst handleTabActivated = async(activeInfo) => {\n  const tab = await chrome.tabs.get(activeInfo.tabId);\n  if (tab && tab.url && tab.url.startsWith('http')) {\n    mStore.initSetting(tab);\n  }\n};\n\nonMounted(async()=>{\n  doRefresh();\n  mStore.loadDict(); //加载字典数据\n  chrome.tabs.onActivated.addListener(handleTabActivated);\n  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });\n  if (tab && tab.url && tab.url.startsWith('http')) {\n    mStore.initSetting(tab);\n    const params = {type: utilSrv.msgTypeNetRule, link: tab.url};\n    await messageSrv.doSendMessage(params);\n  }\n});\n\nonBeforeUnmount(() => {\n  chrome.tabs.onActivated.removeListener(handleTabActivated);\n});\n\nconst setConfig = async(isReset=false)=>{\n  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });\n  if (tab && tab.url && tab.url.startsWith('http')) {\n    mStore.svSetting(tab, isReset);\n  }\n};\n\nconst doRefresh = async () => {\n  const params = {type: utilSrv.msgTypeTaskCount};\n  const state  = await messageSrv.doSendMessage(params);\n  if (state && state >= 0) {\n    dataState.n_task = parseInt(state);\n  } else if (state === 0 || state === '0') {\n    dataState.n_task = 0;\n  }\n};\n\nconst clearData = async (sType) => {\n  const params = {type:utilSrv.msgTypeClearCache, refType: sType};\n  if (sType > 1) {\n    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });\n    if (tab && tab.url) {\n      params.url = tab.url;\n    }\n  }\n  const state = await messageSrv.doSendMessage(params);\n  let sData = '缓存清理';\n  switch (sType) {\n    case 0:\n      sData = '数据清理';\n      break;\n    case 1:\n      sData = '任务清理';\n      break;\n    case 5:\n      sData = '重置设置';\n      setConfig(true);\n      break;\n  }\n  if (state == 'OK') {\n    if (sType === 1) {\n      dataState.n_task = 0;\n    }\n    Message.success(sData+'完成');\n  } else {\n    Message.error(sData+'失败');\n  }\n};\n</script>\n<style scoped>\n:global(html),\n:global(body),\n:global(#app) {\n  min-height: 100%;\n  min-width: 320px;\n  margin: 0;\n  background: #f4f7fb;\n}\n:global(*) {\n  box-sizing: border-box;\n}\n.app-shell {\n  min-height: 100vh;\n  min-width: 320px;\n  color: #172033;\n  background:\n    radial-gradient(circle at 8% 0%, rgba(59, 130, 246, 0.09), transparent 28%),\n    radial-gradient(circle at 100% 12%, rgba(14, 165, 233, 0.07), transparent 26%),\n    #f4f7fb;\n}\n.main-content {\n  display: grid;\n  width: 100%;\n  min-width: 320px;\n  margin: 0 auto;\n  padding: 12px;\n  gap: 12px;\n}\n.workspace-card {\n  padding: 15px;\n  background: #ffffff;\n  border: 1px solid #e6ebf2;\n  border-radius: 16px;\n  box-shadow: 0 6px 20px rgba(15, 23, 42, 0.045);\n}\n.section-heading {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  margin-bottom: 13px;\n}\n.section-heading.compact {\n  align-items: center;\n  margin-bottom: 10px;\n}\n.section-kicker {\n  display: block;\n  margin-bottom: 2px;\n  color: #2563eb;\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 1px;\n}\n.section-heading h2 {\n  margin: 0;\n  color: #172033;\n  font-size: 16px;\n  line-height: 23px;\n}\n.section-heading p {\n  margin: 3px 0 0;\n  color: #7c879d;\n  font-size: 12px;\n  line-height: 18px;\n}\n.site-domain {\n  overflow: hidden;\n  max-width: 185px;\n  padding: 4px 8px;\n  color: #2563eb;\n  background: #eff6ff;\n  border-radius: 999px;\n  font-size: 11px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.site-switches {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 8px;\n}\n.switch-item {\n  display: flex;\n  align-items: center;\n  min-width: 0;\n  padding: 10px;\n  background: #fbfcfe;\n  border: 1px solid #edf0f5;\n  border-radius: 12px;\n  cursor: pointer;\n}\n.switch-icon {\n  display: grid;\n  width: 36px;\n  height: 36px;\n  flex: none;\n  border-radius: 10px;\n  place-items: center;\n}\n.switch-icon.blue {\n  color: #2563eb;\n  background: #eff6ff;\n}\n.switch-icon.cyan {\n  color: #0891b2;\n  background: #ecfeff;\n}\n.switch-icon.violet {\n  color: #7c3aed;\n  background: #f5f3ff;\n}\n.switch-copy {\n  display: block;\n  min-width: 0;\n  flex: 1;\n  margin: 0 8px;\n}\n.switch-copy strong,\n.switch-copy small {\n  display: block;\n}\n.switch-copy strong {\n  color: #344054;\n  font-size: 12px;\n}\n.switch-copy small {\n  margin-top: 2px;\n  color: #98a2b3;\n  font-size: 10px;\n}\n.maintenance-actions {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(92px, 1fr));\n  gap: 8px;\n  overflow-x: auto;\n}\n.maintenance-actions.three-columns {\n  grid-template-columns: repeat(3, minmax(92px, 1fr));\n}\n.maintenance-action {\n  display: flex;\n  align-items: center;\n  justify-content: flex-start;\n  height: auto;\n  min-height: 58px;\n  padding: 8px 9px;\n  text-align: left;\n  background: #fbfcfe;\n  border: 1px solid #edf0f5;\n  border-radius: 11px;\n}\n.maintenance-action:hover {\n  background: #f8fafc;\n  border-color: #cbd5e1;\n}\n.maintenance-icon {\n  display: inline-grid;\n  width: 33px;\n  height: 33px;\n  flex: none;\n  vertical-align: middle;\n  border-radius: 9px;\n  place-items: center;\n}\n.maintenance-action.amber .maintenance-icon {\n  color: #d97706;\n  background: #fffbeb;\n}\n.maintenance-action.blue .maintenance-icon {\n  color: #2563eb;\n  background: #eff6ff;\n}\n.maintenance-action.cyan .maintenance-icon {\n  color: #0891b2;\n  background: #ecfeff;\n}\n.mainten