import { createApp } from 'vue';
import { Router } from "./router";
import { createPinia } from 'pinia';
import { Button, Icon, Modal, Space, Table, Login, Email, Password, Poptip, Progress, Page, Input,
    Collapse, Panel, Submit, Switch, Divider, Captcha, Spin, Avatar, Message } from 'view-ui-plus'; // 按需导入
import { initJsStore } from "@/static/js/index-db/idb-service";
import { ocHeartBeat } from "@/static/js/base/worker";
import { Thumbmark } from '@thumbmarkjs/thumbmarkjs';
import utilSrv from "@/static/js/base/utils";
import 'view-ui-plus/dist/styles/viewuiplus.css';
import App from '@/app/popup/App.vue';

const pinia = createPinia();
const app = createApp(App);
initJsStore(); //初始化数据库

//初始化设置浏览器指纹数据
const tm = new Thumbmark({});
const tmData = await tm.get();
if (tmData && tmData.thumbmark) {
    await chrome.storage.local.set({ 
        ['_fp']: tmData.thumbmark
    });
}

ocHeartBeat().then(()=>{//后端服务正常的情况
   utilSrv.Write(utilSrv.INFO, "offscreen服务OK");
}).catch((err)=>{
    utilSrv.Write(utilSrv.ERROR, "offscreen服务异常", err);
});

app.config.productionTip = false;
app.use(pinia).use(Router);
app.component('Icon', Icon);
app.component('Spin', Spin);
app.component('Page', Page);
app.component('Input', Input);
app.component('Space', Space);
app.component('Login', Login);
app.component('Email', Email);
app.component('Table', Table);
app.component('Modal', Modal);
app.component('Panel', Panel);
app.component('Poptip', Poptip);
app.component('Switch', Switch);
app.component('Submit', Submit);
app.component('Avatar', Avatar);
app.component('Button', Button);
app.component('Captcha', Captcha);
app.component('Divider', Divider);
app.component('Message', Message);
app.component('Progress', Progress);
app.component('Collapse', Collapse);
app.component('Password', Password);
app.mount('#app');