            <span class="switch-copy">
              <strong>模板采集</strong>
              <small>执行采集模板</small>
            </span>
            <Switch true-color="#7c3aed" false-color="#cbd5e1"
              @on-change="setConfig(false)" v-model="mStore.setting.site_wasm" />
          </label>
        </div>
      </section>

      <section class="workspace-card maintenance-card">
        <div class="section-heading compact">
          <div>
            <h2>快捷维护</h2>
          </div>
          <Button v-if="mStore.isManager" type="text" size="small" icon="md-refresh" @click="doRefresh">刷新任务</Button>
        </div>
        <div class="maintenance-actions" :class="{ 'three-columns': !mStore.isManager }">
          <Button class="maintenance-action blue" type="text" @click="clearData(5)">
            <span class="maintenance-icon"><Icon type="ios-redo-outline" size="21" /></span>
            <span class="maintenance-label">重置设置<small>当前站点</small></span>
          </Button>
          <Button class="maintenance-action amber" type="text" @click="clearData(99)">
            <span class="maintenance-icon"><Icon type="ios-images-outline" size="21" /></span>
            <span class="maintenance-label">媒体缓存<small>图片 / 视频</small></span>
          </Button>
          <Button v-if="mStore.isManager" class="maintenance-action cyan" type="text" @click="clearData(1)">
            <span class="maintenance-icon"><Icon type="md-refresh-circle" size="21" /></span>
            <span class="maintenance-label">清理任务<small>{{ dataState.n_task }} 条待处理</small></span>
          </Button>
          <Button class="maintenance-action red" type="text" @click="clearData(0)">
            <span class="maintenance-icon"><Icon type="ios-trash-outline" size="21" /></span>
            <span class="maintenance-label">数据清空<small>全部本地数据</small></span>
          </Button>
        </div>
      </section>

      <CTools />
