<script setup>
import { Button, Icon, Switch, Message } from 'view-ui-plus';
import messageSrv from "@/static/js/base/m-sender";
import utilSrv from "@/static/js/base/utils";
import { onMounted, onBeforeUnmount, reactive } from 'vue';
import { useStore } from '@/app/store/index';
import CTools from './components/tools.vue';
import CEditor from './components/editor.vue';
import CDataset from './components/dataset.vue';
import CFeedback from './components/feedback.vue';
import CProfile from './components/profile.vue';

const mStore = useStore();
const dataState = reactive({n_task:0});

//切换tab的情况加载模版
const handleTabActivated = async(activeInfo) => {
  const tab = await chrome.tabs.get(activeInfo.tabId);
  if (tab && tab.url && tab.url.startsWith('http')) {
    mStore.initSetting(tab);
  }
};

onMounted(async()=>{
  doRefresh();
  mStore.loadDict(); //加载字典数据
  chrome.tabs.onActivated.addListener(handleTabActivated);
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  if (tab && tab.url && tab.url.startsWith('http')) {
    mStore.initSetting(tab);
    const params = {type: utilSrv.msgTypeNetRule, link: tab.url};
    await messageSrv.doSendMessage(params);
  }
});

onBeforeUnmount(() => {
  chrome.tabs.onActivated.removeListener(handleTabActivated);
});

const setConfig = async(isReset=false)=>{
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  if (tab && tab.url && tab.url.startsWith('http')) {
    mStore.svSetting(tab, isReset);
  }
};

const doRefresh = async () => {
  const params = {type: utilSrv.msgTypeTaskCount};
  const state  = await messageSrv.doSendMessage(params);
  if (state && state >= 0) {
    dataState.n_task = parseInt(state);
  } else if (state === 0 || state === '0') {
    dataState.n_task = 0;
  }
};

const clearData = async (sType) => {
  const params = {type:utilSrv.msgTypeClearCache, refType: sType};
  if (sType > 1) {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (tab && tab.url) {
      params.url = tab.url;
    }
  }
  const state = await messageSrv.doSendMessage(params);
  let sData = '缓存清理';
  switch (sType) {
    case 0:
      sData = '数据清理';
      break;
    case 1:
      sData = '任务清理';
      break;
    case 5:
      sData = '重置设置';
      setConfig(true);
      break;
  }
  if (state == 'OK') {
    if (sType === 1) {
      dataState.n_task = 0;
    }
    Message.success(sData+'完成');
  } else {
    Message.error(sData+'失败');
  }
};
</script>
