<template>
    <span class="version-entry" :class="{ 'has-update': curState.hasUpdate }"
        :title="curState.hasUpdate? '发现新版本，点击查看详情' : '查看版本信息'"
        @click="openVersion">
        <Icon :type="curState.hasUpdate ? 'ios-cloud-download' : 'ios-git-branch'" size="13" />
        <span class="version-text">
            {{ curState.hasUpdate ? `新版本 v${latest}` : `v${curState.current || '--'}` }}
        </span>
        <i v-if="curState.hasUpdate" class="update-dot"></i>
    </span>

    <Modal v-model="mVersion" title="版本信息" :footer-hide="true" :mask-closable="true">
        <div class="version-modal">
            <div class="version-banner" :class="{ 'is-new': curState.hasUpdate }">
                <span class="banner-icon"><Icon :type="curState.hasUpdate ? 'ios-cloud-download' : 'ios-checkmark-circle' " size="22" /></span>
                <div>
                    <strong>{{ curState.hasUpdate ? `发现新版本 v${latest}` : '当前已是最新版本' }}</strong>
                    <p>{{ curState.hasUpdate ? '建议尽快更新，体验最新功能与修复。' : `版本号 v${curState.current || '--'}` }}</p>
                </div>
            </div>

            <div class="version-rows">
                <div class="version-row">
                    <span>当前版本</span>
                    <strong>v{{ curState.current || '--' }}</strong>
                </div>
                <div class="version-row">
                    <span>最新版本</span>
                    <strong :class="{ 'new-ver': curState.hasUpdate }">v{{ latest || curState.current || '--' }}</strong>
                </div>
                <div v-if="mStore.version && mStore.version.date" class="version-row">
                    <span>发布时间</span>
                    <strong>{{ mStore.version.date}}</strong>
                </div>
            </div>

            <template v-if="curState.hasUpdate">
                <div class="notes-title">更新内容</div>
                <div v-if="mStore.version && mStore.version.data" class="notes-list">
                    <pre v-html="mStore.version.data"></pre>
                </div>
                <div v-else class="notes-empty">本次更新为功能优化与体验提升。</div>
            </template>

            <div class="version-actions">
                <Button v-if="curState.hasUpdate" type="primary" long size="large" @click="doDownload">
                    <Icon type="ios-download-outline" /> 立即下载更新
                </Button>
                <Button v-if="curState.hasUpdate" long size="large" @click="doIgnore">稍后再说</Button>
                <Button v-else long size="large" :loading="isChecking" @click="reCheck">重新检测</Button>
            </div>
        </div>
    </Modal>
</template>
<script setup>
import { ref, reactive, watch, onMounted, computed } from 'vue';
import { Button, Icon, Modal, Message } from 'view-ui-plus';
import { useStore } from '@/app/store/index';

const mStore = useStore();
const mVersion  = ref(false);
const isChecking= ref(false);
//状态数据资料信息
const curState = reactive({
    ignoreVer:'',
    hasUpdate:false,
    current: process.env.APP_VERSION,
    currentCode: process.env.APP_VERCODE,
});

//版本变动的情况
watch(() => mStore.version, ()=>{
    init();
});

//最新的版本
const latest = computed(()=>{
    if (!mStore.version) {
        return '';
    }
    return mStore.version.name;
});

//初始化业务逻辑
const init = async() => {
    try {
        const manifest = chrome.runtime.getManifest();
        if (manifest && manifest?.version) {
            curState.current = manifest?.version;
        }
    } catch(err) {
        //
    }
    const data = await chrome.storage.local.get('ignoreVersion');
    curState.ignoreVer = data?.ignoreVersion || '';
    if (mStore.version && mStore.version.ver 
            && mStore.version.ver > curState.currentCode 
            && curState.ignoreVer != latest.value) {
        curState.hasUpdate = true; //有新版本需要更新的情况
    }
}
//当前的版本数据资料信息
onMounted(async()=>{
    init(); //初始化业务逻辑
});

//打开版本详情弹窗
const openVersion = async() => {
    mVersion.value = true;
};

//重新检测版本
const reCheck = async() => {
    isChecking.value = true;
    await mStore.loadDict();
    isChecking.value = false;
    const isNew = mStore.version && mStore.version.ver > curState.currentCode;
    Message.success(isNew ? '发现新版本' : '当前已是最新版本');
    curState.hasUpdate = isNew; //重新展示升级
    await chrome.storage.local.remove('ignoreVersion');
};

//跳转到下载地址
const doDownload = async() => {
    let link = mStore.version.url;
    if (!link) {//降级使用插件主页地址
        try {
            link = chrome.runtime.getManifest().homepage_url || '';
        } catch(err) {
            link = '';
        }
    }
    if (!link) {
        Message.info('暂未配置下载地址');
        return;
    }
    await chrome.tabs.create({url: link});
};

//忽略本次版本提示
const doIgnore = async() => {
    curState.ignoreVer = latest.value;
    curState.hasUpdate = false;
    const sData = {ignoreVersion:curState.ignoreVer};
    await chrome.storage.local.set(sData);
    mVersion.value = false;
    Message.success('已忽略该版本提示');
};

</script>
