mments';\r\n\r\nconst cPanel  = ref('');\r\nconst mStore = useStore();\r\nconst itemsStore = useItemsStore();\r\nconst mediaStore = useMediaStore();\r\nconst commsStore = useCommentsStore();\r\nconst productsStore = useProductsStore();\r\n\r\n//是否包含数据\r\nconst isData = computed(()=>{\r\n  if (mStore.isManager) {\r\n    return true;\r\n  }\r\n  return !!iTitle.value || !!pTitle.value || !!cTitle.value;\r\n});\r\n\r\nconst iTitle = computed(()=>{\r\n  const domain = mStore.curDomain;\r\n  const items = mStore.dict.items || [];\r\n  const dtItem = items.find((item)=>{\r\n    return domain.includes(item.value);\r\n  });\r\n  return dtItem? dtItem.label:'';\r\n});\r\n\r\nconst pTitle = computed(()=>{\r\n  const domain = mStore.curDomain;\r\n  const items = mStore.dict.products || [];\r\n  const dtItem = items.find((item)=>{\r\n    return domain.includes(item.value);\r\n  });\r\n  return dtItem? dtItem.label:'';\r\n});\r\n\r\nconst cTitle = computed(()=>{\r\n  const domain = mStore.curDomain;\r\n  const items = mStore.dict.comments || [];\r\n  const dtItem = items.find((item)=>{\r\n    return domain.includes(item.value);\r\n  });\r\n  return dtItem? dtItem.label:'';\r\n});\r\n\r\nconst dataDescription = computed(() => {\r\n  if (iTitle.value) {\r\n    return `当前已识别为${iTitle.value}页面，可在下方查看、导出与维护采集结果。`;\r\n  }\r\n  if (pTitle.value) {\r\n    return `当前已识别为${pTitle.value}页面，可在下方查看、导出与维护采集结果。`;\r\n  }\r\n  return '按当前站点集中查看采集结果、图片和视频资源。';\r\n});\r\n</script>\r\n<style scoped>\r\n.data-center {\r\n  display: grid;\r\n  gap: 12px;\r\n}\r\n.data-card {\r\n  padding: 15px;\r\n  background: #ffffff;\r\n  border: 1px solid #e6ebf2;\r\n  border-radius: 16px;\r\n  box-shadow: 0 6px 20px rgba(15, 23, 42, 0.045);\r\n}\r\n.section-heading {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  justify-content: space-between;\r\n  gap: 12px;\r\n  margin-bottom: 13px;\r\n}\r\n.section-kicker {\r\n  display: block;\r\n  margin-bottom: 2px;\r\n  color: #2563eb;\r\n  font-size: 10px;\r\n  