<template>
    <div class="profile-wrapper">
        <section class="account-card" :class="{ 'is-guest': !mStore.user }">
            <template v-if="mStore.user">
                <div class="account-main">
                    <Avatar class="account-avatar" :style="{ background: mColor }" shape="square" size="large">
                        {{ mAvatar }}
                    </Avatar>
                    <div class="account-copy">
                        <div class="account-name-row">
                            <strong class="account-name">{{ displayName }}</strong>
                            <CVersion />
                        </div>
                        <span class="account-id">{{ mStore.user.username }}&nbsp;&nbsp;
                            <span class="status-pill"><i></i>已登录</span>
                        </span>
                    </div>
                </div>
                <div class="account-actions">
                    <label v-if="mStore.user.isDev===1" class="developer-toggle" title="开启后显示脚本、模板开发管理功能">
                        <Icon type="ios-code-working" size="17" />
                        <span>开发者</span>
                        <Switch v-model="developerEnabled" size="small" />
                    </label>
                    <Button class="signout-button" type="text" size="small" @click="doSignout">
                        <Icon type="ios-log-out" />退出
                    </Button>
                </div>
            </template>
            <template v-else>
                <div class="guest-copy">
                    <img src="/icons/icon_64.png" class="brand-mark" />
                    <div>
                        <strong>工作台&nbsp;&nbsp;<CVersion /></strong>
                        <p>登录后同步工具与开发配置</p>
                    </div>
                </div>
                <Button class="login-button" type="primary" @click="setPopType(1)">
                    账号登录
                    <Icon type="ios-arrow-forward" />
                </Button>
            </template>
        </section>

        <div class="device-badge">
            <button class="device-card" type="button" @click="setPopType(3)">                
                <span class="device-icon"><Icon type="ios-laptop" size="22" /></span>
                <span class="device-copy">
                    <span class="device-title">
                        <span style="padding-right: 6px;">{{ mDevice.device || '配置当前设备' }}</span>
                        <Badge :count="taskCount" :show-zero="false" :overflow-count="99"></Badge>
                    </span>
                    <span class="device-summary">
                        {{ mDevice.alise || '补充设备名称、用途与并发限制' }}
                    </span>
                </span>

                <span v-if="mDevice.limit_tasks" class="device-limit">{{ mDevice.limit_tasks }} 并发</span>
                <Icon class="device-arrow" type="ios-arrow-forward" size="16" />
            </button>
        </div>
    </div>

    <Modal v-model="mState.isPop" :title="popTitle" :footer-hide="true" :closable="closable" :mask-closable="false">
        <div class="pop-modal" v-if="mState.popType == 1 || mState.popType == 2">
            <Login @on-submit="doSubmit" ref="form">
                <template v-if="mState.popType == 2">
                    <UserName name="nickname" :rules="mNicknameRule" placeholder="请输入账号昵称" />
                </template>
                <UserName name="username" :rules="mUsernameRule" :placeholder="phUsername" />
                <template v-if="mState.popType == 2">
                    <Poptip trigger="focus" placement="right" width="240">
                        <Password name="password" :rules="mPasswordRule" placeholder="至少6位密码，区分大小写" @on-change="doChangePassword" />
                        <template #content>
                        <div class="pop-modal-tip">
                            <div class="pop-modal-tip-title" :class="passwordTip.class">
                                强度：{{ passwordTip.strong }}
                            </div>
                            <Progress :percent="passwordTip.percent" hide-info :stroke-width="6" :stroke-color="passwordTip.color" />
                            <div class="pop-modal-tip-desc">
                                请至少输入 6 个字符。请不要使用容易被猜到的密码。
                            </div>
                        </div>
                        </template>
                    </Poptip>
                    <Password name="passwordConfirm" :rules="mPasswordConfirmRule" placeholder="确认密码" />
                </template>
                <template v-else>
                    <Password name="password" />
                </template>
                <Captcha v-if="mState.captcha" class="captcha" name="captcha" :count-down="0" @on-get-captcha="doCaptcha">
                    <template #text>
                    <img :src="mState.captcha">
                    </template>
                </Captcha>
                <Submit>{{ mState.popType == 1? '登 录':'注 册' }}</Submit>
            </Login>
            <div class="account-jump">
                <template v-if="mState.popType == 1">尚未创建账号，去<span @click="setPopType(2)">注册</span></template>
                <template v-else>我已创建账号，去<span @click="setPopType(1)">登录</span></template>
            </div>
        </div>
        <div class="pop-modal device-form" v-else>
            <div class="form-intro">
                <span class="form-intro-icon"><Icon type="ios-laptop" size="22" /></span>
                <div>
                    <strong>当前设备信息</strong>
                    <p>用于区分任务执行设备并控制同时打开的标签页数量。</p>
                </div>
            </div>
            <Space direction="vertical" type="flex" size="large">
                <div class="field-block">
                    <label>设备名称</label>
                    <Input v-model="mDevice.device" size="large" placeholder="例如：办公室主机" />
                </div>
                <div class="field-block">
                    <label>用途备注</label>
                    <Input v-model="mDevice.alise" size="large" placeholder="例如：内容采集与素材整理" />
                </div>
                <div class="field-block">
                    <label>任务并发</label>
                    <Input v-model="mDevice.limit_tasks" size="large" type="number" placeholder="允许同时打开的标签页数量" />
                </div>
                <Button type="primary" long size="large" @click="setDevice">保存设备信息</Button>
            </Space>
        </div>
    </Modal>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { useStore } from '@/app/store/index';
import utilSrv from "@/static/js/base/utils";
import { Login, UserName, Password, Modal, Progress,
  Poptip, Message, Space, Input, Button, Avatar, Badge, Icon, Switch } from 'view-ui-plus';
import {captcha, captchaCheck, signIn, signOut,
  register, deviceUpdate} from "@/app/static/api.js";
import { xClearLogin, xInitLogin, xSetLogin,
  xIsLogin } from "@/static/js/base/request";
import CVersion from './version.vue';

const props = defineProps({
    taskCount: {
        type: Number,
        default: 0
    }
});

const mStore = useStore();
const form = ref(null);
const closable = ref(true);
const colorList = ['#3b82f6', '#7c3aed', '#0891b2', '#2563eb'];
const mState = reactive({isPop:false, popType:0,
    password:'', sumid:'', captcha:''});
const mDevice= reactive({device:'', alise:'', limit_tasks:''});

const taskCount = computed(() => props.taskCount || 0);
const displayName = computed(() => {
    if (!mStore.user) {
        return '未登录';
    }
    return mStore.user.realName || mStore.user.username || 'xTools 用户';
});
const developerEnabled = computed({
    get: () => mStore.developerMode,
    set: async(value) => {
        await mStore.setDeveloperMode(value);
        Message.success(value ? '开发者模式已开启' : '开发者模式已关闭');
    }
});

const mPasswordRule = [
    {
        required: true, message: '密码不能为空！', trigger: 'change'
    },
    {
        min: 6, message: '密码不能少于6位！', trigger: 'change'
    }
];

const mNicknameRule = [
    {
        required: true, message: '用户昵称不能为空！', trigger: 'change'
    }
];

const mUsernameRule = [
    {
        required: true, message: '用户账号不能为空！', trigger: 'change'
    }
];

const validatePassCheck = (rule, value, callback) => {
    if (value !== form.value.formValidate.password) {
        callback(new Error('两次输入的密码不匹配！'));
    } else {
        callback();
    }
};

const mPasswordConfirmRule = [
    {
        required: true, message: '确认密码不能为空！', trigger: 'change'
    },
    { validator: validatePassCheck, trigger: 'change' },
];

const phUsername = computed(()=>{
    if (mState.popType == 1) {
        return '登录账号/邮箱/手机号码';
    } else {
        return '请输入注册邮箱/手机号码';
    }
});

const popTitle = computed(()=>{
    if (mState.popType == 3) {
        return '编辑设备信息';
    }
    return mState.popType == 1? '账号登录':'账号注册';
});

const mColor = computed(()=>{
    let idx = new Date().getTime();
    if (mStore.user) {
        idx = mStore.user.userId || mStore.user.username?.length || 0;
    }
    return colorList[Math.abs(Number(idx) || 0)%colorList.length];
});
const mAvatar = computed(()=>{
    if (!mStore.user) {
        return '?';
    }
    let nName = mStore.user.realName || mStore.user.username || 'X';
    nName = nName.replace(/[^\u4e00-\u9fa5a-zA-Z0-9]/g, '');
    return nName.substring(0, 1).toUpperCase() || 'X';
});
const passwordTip = computed(()=>{
    let strong = '强';
    let className = 'strong';
    let percent = 0;
    let color = '#19be6b';
    const spReg = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?~`]/;
    const checks = {
        hasLower: /[a-z]/.test(mState.password),
        hasUpper: /[A-Z]/.test(mState.password),
        hasNumber: /\d/.test(mState.password),
        hasSpecial: spReg.test(mState.password),
    };

    if (checks.hasLower) percent++;
    if (checks.hasUpper) percent++;
    if (checks.hasNumber) percent++;
    if (checks.hasSpecial) percent++;

    if (percent <= 2) {
        strong = '弱';
        className = 'low';
        color = '#ed4014';
    } else if (percent <= 3) {
        strong = '中';
        className = 'medium';
        color = '#ff9900';
    }

    return {
        strong,
        class: 'pop-modal-tip-' + className,
        percent: percent * 10,
        color
    };
});

const doChangePassword = (val) => {
    mState.password = val;
};

const setPopType = async (popType=1) => {
    mState.popType = popType;
    mState.isPop = true;
    if (popType !== 3) {
        doCaptcha();
    }
};

const doCaptcha = async () => {
    const data = await captcha({sumid:mState.sumid});
    if (data && data.image) {
        mState.sumid = data._cap;
        mState.captcha = 'data:image/png;base64,'+data.image;
    }
};

onMounted(async()=>{
    const data = await xInitLogin();
    if (data && data.sign) {
        await mStore.signIn(data.sign, data.user);
        await mStore.loadDeveloperMode();
    } else {
        logPopCheck();
    }
    const devData = await chrome.storage.local.get('deviceInfo');
    if (devData && devData.deviceInfo) {
        mDevice.device = devData.deviceInfo.device;
        mDevice.alise = devData.deviceInfo.alise;
        mDevice.limit_tasks = devData.deviceInfo.limit_tasks;
    }
    chrome.storage.onChanged.addListener(async () => {
        const isLogin = await xIsLogin();
        if (!isLogin) {
            await mStore.setDeveloperMode(false);
            mStore.signIn('', null);
            await signOut();
        }
    });
});

const logPopCheck = async() => {
    const nS = (new Date()).getTime() / 1000;
    const data = await chrome.storage.local.get('_inS');
    if (!data['_inS']) {
        await chrome.storage.local.set({_inS:nS});
    }
    if (data['_inS'] &&  Math.abs(nS - data['_inS']) > 86400) {
        closable.value = false;
        setPopType(1);
    }
};

const doSubmit = async (valid, formValue) => {
    if (!valid) {return;}
    if (mState.popType == 1) {
        doLogin(formValue);
    } else {
        doRegister(formValue);
    }
};

const setDevice = async() => {
    if (!mDevice.device) {
        Message.error('设备名称不能为空');
        return;
    }
    if (!mDevice.alise) {
        Message.error('设备用途备注不能为空');
        return;
    }
    if (!mDevice.limit_tasks || mDevice.limit_tasks < 1) {
        Message.error('并发限制必须大于0');
        return;
    }
    const device_id = await utilSrv.DeviceId();
    const param = {device:mDevice.device, alise:mDevice.alise,
         device_id: device_id, limit_tasks:mDevice.limit_tasks};
    const data = await deviceUpdate(param);
    if (data) {
        Message.success('设备信息保存成功');
        mState.isPop = false;
        await chrome.storage.local.set({deviceInfo:{...mDevice}});
    }
};

const setLogin = async(data) => {
    await mStore.signIn(data.sign, data.user);
    await mStore.loadDeveloperMode();
    Message.success('账号登录成功');
    mState.isPop = false;
    await xSetLogin(data);
};

const doRegister= async ({ nickname, username, password, captcha }) => {
    const param = {sumid:mState.sumid, vcode:captcha};
    const xData = await captchaCheck(param);
    if (!xData) {
        return;
    }
    param.xtoken = xData.xtoken;
    param.username = username;
    param.nickname = nickname;
    param.password = password;
    param.captcha  = true;
    param.device_id= await utilSrv.DeviceId();
    const data = await register(param);
    if (data && data.user) {
        setLogin(data);
    }
    return data;
};

const doLogin = async ({ username, password, captcha }) => {
    const param = {sumid:mState.sumid, vcode:captcha};
    const xData = await captchaCheck(param);
    if (!xData) {
        return;
    }
    param.xtoken = xData.xtoken;
    param.username = username;
    param.password = password;
    param.captcha  = true;
    param.device_id= await utilSrv.DeviceId();
    const data = await signIn(param);
    if (data && data.user) {
        setLogin(data);
    }
    return data;
};

const doSignout = async() => {
    await signOut();
    await mStore.setDeveloperMode(false);
    mStore.signIn('', null);
    await xClearLogin();
    Message.success('账号已退出');
};
</script>
