               <Icon type=\"ios-code-working\" size=\"17\" />\r\n                        <span>开发者</span>\r\n                        <Switch v-model=\"developerEnabled\" size=\"small\" />\r\n                    </label>\r\n                    <Button class=\"signout-button\" type=\"text\" size=\"small\" @click=\"doSignout\">\r\n                        <Icon type=\"ios-log-out\" />退出\r\n                    </Button>\r\n                </div>\r\n            </template>\r\n            <template v-else>\r\n                <div class=\"guest-copy\">\r\n                    <img src=\"/icons/icon_64.png\" class=\"brand-mark\" />\r\n                    <div>\r\n                        <strong>工作台&nbsp;&nbsp;<CVersion /></strong>\r\n                        <p>登录后同步工具与开发配置</p>\r\n                    </div>\r\n                </div>\r\n                <Button class=\"login-button\" type=\"primary\" @click=\"setPopType(1)\">\r\n                    账号登录\r\n                    <Icon type=\"ios-arrow-forward\" />\r\n                </Button>\r\n            </template>\r\n        </section>\r\n\r\n        <div class=\"device-badge\">\r\n            <button class=\"device-card\" type=\"button\" @click=\"setPopType(3)\">                \r\n                <span class=\"device-icon\"><Icon type=\"ios-laptop\" size=\"22\" /></span>\r\n                <span class=\"device-copy\">\r\n                    <span class=\"device-title\">\r\n                        <span style=\"padding-right: 6px;\">{{ mDevice.device || '配置当前设备' }}</span>\r\n                        <Badge :count=\"taskCount\" :show-zero=\"false\" :overflow-count=\"99\"></Badge>\r\n                    </span>\r\n                    <span class=\"device-summary\">\r\n                        {{ mDevice.alise || '补充设备名称、用途与并发限制' }}\r\n                    </span>\r\n                </span>\r\n\r\n                <span v-if=\"mDevice.limit_tasks\" class=\"device-limit\">{{ mDevice.limit_tasks }} 并发</span>\r\n                <Icon class=\"device-arrow\" type=\"ios-arrow-forward\" size=\"16\" />\r\n            </button>\r\n        </div>\r\n    </div>\r\n\r\n    <Modal v-model=\"mState.isPop\" :title=\"popTitle\" :footer-hide=\"true\" :closable=\"closable\" :mask-closable=\"false\">\r\n        <div class=\"pop-modal\" v-if=\"mState.popType == 1 || mState.popType == 2\">\r\n            <Login @on-submit=\"doSubmit\" ref=\"form\">\r\n                <template v-if=\"mState.popType == 2\">\r\n                    <UserName name=\"nickname\" :rules=\"mNicknameRule\" placeholder=\"请输入账号昵称\" />\r\n                </template>\r\n                <UserName name=\"username\" :rules=\"mUsernameRule\" :placeholder=\"phUsername\" />\r\n                <template v-if=\"mState.popType == 2\">\r\n                    <Poptip trigger=\"focus\" placement=\"right\" width=\"240\">\r\n                        <Password name=\"password\" :rules=\"mPasswordRule\" placeholder=\"至少6位密码，区分大小写\" @on-change=\"doChangePassword\" />\r\n                        <template #content>\r\n                        <div class=\"pop-modal-tip\">\r\n                            <div class=\"pop-modal-tip-title\" :class=\"passwordTip.class\">\r\n                                强度：{{ passwordTip.strong }}\r\n                            </div>\r\n                            <Progress :percent=\"passwordTip.percent\" hide-info :stroke-width=\"6\" :stroke-color=\"passwordTip.color\" />\r\n                            <div class=\"pop-modal-tip-desc\">\r\n                                请至少输入 6 个字符。请不要使用容易被猜到的密码。\r\n                            </div>\r\n                        </div>\r\n                        </template>\r\n                    </Poptip>\r\n                    <Password name=\"passwordConfirm\" :rules=\"mPasswordConfirmRule\" placeholder=\"确认密码\" />\r\n                </template>\r\n                <template v-else>\r\n                    <Password name=\"password\" />\r\n                </template>\r\n                <Captcha v-if=\"mState.captcha\" class=\"captcha\" name=\"captcha\" :count-down=\"0\" @on-get-captcha=\"doCaptcha\">\r\n                    <template #text>\r\n                    <img :src=\"mState.captcha\">\r\n                    </template>\r\n                </Captcha>\r\n                <Submit>{{ mState.popType == 1? '登 录':'注 册' }}</Submit>\r\n            </Login>\r\n            <div class=\"account-jump\">\r\n                <template v-if=\"mState.popType == 1\">尚未创建账号，去<span @click=\"setPopType(2)\">注册</span></template>\r\n                <template v-else>我已创建账号，去<span @click=\"setPopType(1)\">登录</span></template>\r\n            </div>\r\n        </div>\r\n        <div class=\"pop-modal device-form\" v-else>\r\n            <div class=\"form-intro\">\r\n                <span class=\"form-intro-icon\"><Icon type=\"ios-laptop\" size=\"22\" /></span>\r\n                <div>\r\n                    <strong>当前设备信息</strong>\r\n                    <p>用于区分任务执行设备并控制同时打开的标签页数量。</p>\r\n                </div>\r\n            </div>\r\n            <Space direction=\"vertical\" type=\"flex\" size=\"large\">\r\n                <div class=\"field-block\">\r\n                    <label>设备名称</label>\r\n                    <Input v-model=\"mDevice.device\" size=\"large\" placeholder=\"例如：办公室主机\" />\r\n                </div>\r\n                <div class=\"field-block\">\r\n                    <label>用途备注</label>\r\n                    <Input v-model=\"mDevice.alise\" size=\"large\" placeholder=\"例如：内容采集与素材整理\" />\r\n                </div>\r\n                <div class=\"field-block\">\r\n                    <label>任务并发</label>\r\n                    <Input v-model=\"mDevice.limit_tasks\" size=\"large\" type=\"number\" placeholder=\"允许同时打开的标签页数量\" />\r\n                </div>\r\n                <Button type=\"primary\" long size=\"large\" @click=\"setDevice\">保存设备信息</Button>\r\n            </Space>\r\n        </div>\r\n    </Modal>\r\n</template>\r\n<script setup>\r\nimport { computed, on