import { defineStore } from 'pinia'
import utilSrv from "@/static/js/base/utils";
import { MediaRefType } from "@/static/js/index-db/idb-schema";
import { MediaSrv } from '@/static/js/index-db/media.srv';

const mediaSrv = new MediaSrv();
export const useMediaStore = defineStore('Media', {
    state: () => {
      return {
        video: [],
        image: [],
        imgTotal: 0,
        vodTotal: 0,
        mPagesize: 10,
      }
    },
    actions: {
      async deleteMedia(id, sType) {
        if (sType == 1) {
          this.image = this.image.filter((item)=>item.id != id);
        } else {
          this.video = this.video.filter((item)=>item.id != id);
        }
        mediaSrv.remove(id);
      },
      async loadImage(pageNum=1, url='') {
        this.imgTotal = await mediaSrv.Count(MediaRefType.image, url);
        if (this.imgTotal < 1) {
          this.image = [];
          return
        }
        const data = await mediaSrv.GetList(pageNum, this.mPagesize,
          MediaRefType.image, url);
        if (!data || !Array.isArray(data)) {
          return;
        }
        const items = data.map((item)=>{
          item.created_at = utilSrv.DateStr(item.created_at, 'Y-m-d');
          return {...item, ...item.meta};
        });
        this.image = items;
      },
      async loadVideo(pageNum=1, url='') {
        this.vodTotal = await mediaSrv.Count(MediaRefType.video, url);
        if (this.vodTotal < 1) {
          this.video = [];
          return
        }

        const data = await mediaSrv.GetList(pageNum, this.mPagesize,
          MediaRefType.video, url);
        if (!data || !Array.isArray(data)) {
          return;
        }
        const items = data.map((item)=>{
          item.created_at = utilSrv.DateStr(item.created_at, 'Y-m-d');
          return {...item, ...item.meta};
        });
        this.video = items;
      },
    },
});