import { defineStore } from 'pinia'
import utilSrv from "@/static/js/base/utils";
import { CacheRefType } from "@/static/js/index-db/idb-schema";
import { CacheSrv } from '@/static/js/index-db/cache.srv';

const cacheSrv = new CacheSrv();
export const useDevelopStore = defineStore('Develop', {
    state: () => {
      return {
        script: [],
        template: [],
        mPagesize: 10,
        curDomain: '',
      }
    },
    getters: {
      isManager: (state) =>{
        return state.user && state.user.isManager;
      },
      isDeveloper: (state) =>{
        return Boolean(state.user && state.developerMode);
      }
    },
    actions: {
      async loadTemplate(limit=999) {
        const data = await cacheSrv.GetList(limit, CacheRefType.template);
        this.template = data.map((item)=>{
          item.name   = item.meta?.name || '-';
          item.author = item.meta?.author || '-';
          item.remark = item.meta?.remark || '-';
          item.uuid   = item.meta?.uuid || '';
          item.created_at = utilSrv.DateStr(item.created_at, 'Y-m-d');
          return item;
        });
      },
      async deleteTemplate(sKey) {
        try {
          const res = await cacheSrv.removeCache(sKey);
          const items = this.template.filter(item => item.skey !== sKey);
          this.template = items; //替换
          return res
        } catch (err) {
          return -1
        }
      },
      async putTemplate(meta) {
        const sKey = 'template@'+meta.name;
        const res = await cacheSrv.SetCache(sKey, CacheRefType.template, meta);
        const items = this.template.filter(item => item.skey !== sKey);
        const sDate= new Date();
        const data = {skey:sKey, meta:meta, 
          ref_type:CacheRefType.template, created_at: sDate.getTime()};
        data.name = data.meta?.name || '-';
        data.uuid = data.meta?.uuid || '';
        data.author = data.meta?.author || '-';
        data.remark = data.meta?.remark || '-';
        data.created_at = utilSrv.DateStr(data.created_at, 'Y-m-d');
        items.unshift(data); //头部加入脚本记录
        this.template = items;
        return res;
      },
      async loadScript(limit=999) {
        const data = await cacheSrv.GetList(limit, CacheRefType.script);
        this.script= data.map((item)=>{
            item.name = item.meta?.name || '-';
            item.author = item.meta?.author || '-';
            item.version = item.meta?.version || '-';
            item.description = item.meta?.description || '-';
            item.created_at = utilSrv.DateStr(item.created_at, 'Y-m-d');
            return item;
        });
      },
      async deleteScript(sKey) {
        try {
            const res = await cacheSrv.removeCache(sKey);
            const items = this.script.filter(item => item.skey !== sKey);
            this.script = items; //替换
            return res
        } catch (err) {
            return -1
        }
      },
      async putScript(meta) {
        const sKey = 'script@'+meta.name;
        const res = await cacheSrv.SetCache(sKey, CacheRefType.script, meta);
        const items = this.script.filter(item => item.skey !== sKey);
        const sDate= new Date();
        const data = {skey:sKey, meta:meta, 
          ref_type:CacheRefType.script, created_at: sDate.getTime()};
        data.name = data.meta?.name || '-';
        data.author = data.meta?.author || '-';
        data.version = data.meta?.version || '-';
        data.remark = data.meta?.remark || '-';
        data.uuid = data.meta?.uuid || '';
        data.created_at = utilSrv.DateStr(data.created_at, 'Y-m-d');
        items.unshift(data); //头部加入脚本记录
        this.script = items;
        return res;
      },
      async runScript(es5Code, data) {
        const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
        if (!tab || !tab.url || !tab.url.startsWith('http')) {
          throw Error('当前tab非HTTP协议无法执行');
        }
        const sKey = await utilSrv.Sdomain(tab.url);
        if (!sKey) {//域名地址提取失败
          throw Error('域名地址提取失败');
        }
        const meta = {from:'x.script', id:(data && data.id)? data.id:0, is_window:0, link:tab.url, priority:0, status:2,
          opcmd:0, script:es5Code, run_ctx:'content_script', script_uuid:'', timeout:3};
        if (data && data.uuid) {//数据业务逻辑
          meta.script_uuid = data.uuid;
          meta.script = ''; //清空脚本内容-使用服务端下发
        }
        await cacheSrv.SetCache(sKey, CacheRefType.domain, meta);
        await chrome.tabs.reload(tab.id);
      }
    },
});