import { defineStore } from 'pinia'
import utilSrv from "@/static/js/base/utils";
import { ItemsSrv } from '@/static/js/index-db/items.srv';

const itemsSrv = new ItemsSrv();
export const useItemsStore = defineStore('Items', {
    state: () => {
      return {
        items: [],
        total: 0,
        mPagesize: 10,
      }
    },
    actions: {
      async delete(sn) {
        this.items = this.items.filter((item)=>item.sn != sn);
        itemsSrv.remove(sn);
      },
      async load(pageNum=1, url='') {
        this.total = await itemsSrv.Count( url);
        if (this.total < 1) {
          this.items = [];
          return
        }

        const data = await itemsSrv.GetList(pageNum, this.mPagesize, url);
        if (!data || !Array.isArray(data)) {
          return;
        }
        const items = data.map((item)=>{
          item.created_at = utilSrv.DateStr(item.created_at, 'Y-m-d');
          return {...item, ...item.meta};
        });
        this.items = items;
      },
    },
});